-- Lane A figures for None: generated by build_load_sql.py, do not hand-edit.
-- 5 figures across 4 families, from scripts/lane-a-pilot/specs.json.
-- Entries are resolved by natural key, so this file is portable between environments.

begin;

-- 1. The renderer families this batch INTRODUCES (DECISION-0115: a row, not a CHECK).
-- Reused without introducing: none
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('dna_ladder', 'DNA as a paired, antiparallel ladder', 'Two sugar-phosphate backbones with base pairs as rungs, drawn flat rather than helical. The spec names ONE strand''s bases and the renderer derives the partner from the pairing rule and the number of hydrogen bonds from the pair, so a mispaired base cannot be drawn. One orientation flag sets both direction arrowheads, so the two strands cannot be made to run the same way.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('electrochemical_cell', 'Galvanic cell diagram', 'Two half-cells with an electrode in each, an external circuit through a measuring device, and a salt bridge whose ends are below both solution surfaces and touch neither electrode. Every direction is DERIVED from one fact, which side the anode is on: electrons leave the anode through the wire, cations move toward the cathode and anions toward the anode, so no arrow in the figure can contradict another.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('membrane_bilayer', 'Fluid mosaic membrane in cross-section', 'Two leaflets of phospholipids -- hydrophilic heads facing the water on both sides, hydrophobic tails meeting in the interior -- with proteins, steroids, glycoproteins and glycolipids embedded in them. Each inclusion''s geometry follows from its KIND: a protein crosses both leaflets, a steroid sits among the tails and reaches neither surface, and every carbohydrate chain is drawn on the extracellular face. The spec chooses the kind and the x position, never the y.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('organelle', 'Double-membraned organelle regions', 'A chloroplast or a mitochondrion drawn as LABELLED REGIONS rather than as an anatomical illustration: an outer and an inner membrane, and inside the inner one either stacks of thylakoid discs (the grana) or flat-tipped folds of the membrane itself (the cristae). The entries these serve author regions and the process that happens in each, so the contract is whether each region is present, enclosed by the right boundary and named where it is. The cristae leave one band clear right across the matrix, so the matrix label is never drawn over.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;

-- 2. The figures.
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('bio-chloroplast', 'ap_biology', 'organelle', 'Chloroplast: regions and where the reactions happen', 'Stroma, grana, thylakoid', 'Light reactions in the grana; carbon fixation in the stroma around them', 'A chloroplast drawn as regions rather than as an illustration. Inside the double envelope, stacks of thylakoids are the grana, where the light reactions occur; the fluid around them, inside the inner membrane, is the stroma, where the Calvin cycle fixes carbon.', 'A schematic chloroplast: a rounded double boundary, an outer and an inner membrane, enclosing a space. Inside that space sit four stacks of flattened discs. Each disc is a thylakoid and its membrane holds the chlorophyll, organised into two photosystems, along with the electron transport proteins; a stack of them is a granum, and the light reactions happen there. The fluid filling the rest of the space inside the inner membrane is the stroma, and that is where carbon fixation, the Calvin cycle, takes place. The two sets of reactions are therefore in different places: one in a membrane, one in the fluid around it, which is what this diagram is read for. Illustrative data.', '', '', 'Light reactions in the thylakoid membranes; the Calvin cycle in the stroma around them.', true, null, '["Stroma", "Thylakoid membranes", "Grana"]'::jsonb, '{"mode": "grana", "stacks": 4, "discs_per_stack": 4, "unit_note": "each stack of discs is a granum; one disc is a thylakoid, and its membrane holds the pigments", "labels_at": [{"x": 0.5, "y": 0.055, "label": "outer and inner membranes"}, {"x": 0.5, "y": 0.265, "label": "stroma — Calvin cycle", "to": [0.5, 0.345]}, {"x": 0.5, "y": 0.965, "label": "grana — light reactions", "to": [0.5, 0.6]}], "region_check": {"regions": ["stroma", "grana", "thylakoid"]}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=lane-b-gaps-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('bio-mitochondrion', 'ap_biology', 'organelle', 'Mitochondrion: regions and what happens in each', 'Matrix, cristae, space', 'Krebs cycle in the matrix; the gradient across the folded inner membrane', 'A mitochondrion drawn as regions. The inner membrane folds into cristae, which is what gives it more area than the outer one and so more ATP synthase. The matrix inside it holds the Krebs cycle; the space outside it holds the protons.', 'A schematic mitochondrion: a rounded double boundary, an outer and an inner membrane, with the inner one folded back and forth into cristae. The folding is the point, because it gives the inner membrane far more area than the outer one, and that membrane carries the electron transport chain and ATP synthase, so more area means more ATP can be made. The fluid enclosed by the inner membrane is the matrix, where the Krebs cycle runs; it has the lower proton concentration and the higher pH. The narrow region between the two membranes holds the high proton concentration. The difference between those two regions is the gradient that drives ATP synthase. Illustrative data.', '', '', 'Protons high outside the inner membrane, low in the matrix: that difference is the gradient.', true, null, '["Matrix", "Inner mitochondrial membrane", "Intermembrane space / outside the inner membrane"]'::jsonb, '{"mode": "cristae", "folds": 5, "unit_note": "the folds are cristae: more inner-membrane area, so more ATP synthase", "labels_at": [{"x": 0.5, "y": 0.055, "label": "intermembrane space — high H⁺", "to": [0.5, 0.128]}, {"x": 0.5, "y": 0.515, "label": "matrix — Krebs cycle, low H⁺"}, {"x": 0.5, "y": 0.965, "label": "inner membrane folded into cristae", "to": [0.5, 0.845]}], "region_check": {"regions": ["matrix", "inner membrane", "intermembrane"]}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=lane-b-gaps-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('bio-dna-antiparallel', 'ap_biology', 'dna_ladder', 'DNA: two strands, paired and antiparallel', 'Antiparallel strands', 'Each base pairs with one partner, and the two strands run opposite ways', 'The two sugar-phosphate backbones run in opposite directions: read left to right the top strand goes 5'' to 3'', and the bottom strand goes 3'' to 5''. Between them each base is joined to its one partner by hydrogen bonds — two for A with T, three for C with G.', 'A short stretch of DNA drawn flat, as a ladder rather than as a helix. The two sides of the ladder are the sugar-phosphate backbones, two strands of nucleotides, and each carries an arrowhead showing its direction from the 5'' end to the 3'' end. The arrowheads point opposite ways: the top strand''s 3'' end is on the right and the bottom strand''s 3'' end is on the left, which is what antiparallel means. The rungs are the base pairs. Each base on one strand is joined to exactly one base on the other: adenine always with thymine, cytosine always with guanine. The joins are hydrogen bonds, drawn as dashes, and there are two of them in every A with T pair and three in every C with G pair, so the C with G pairs are held together more strongly. Illustrative data.', '', '', 'A pairs only with T, C only with G; the two strands run in opposite directions.', true, null, '["Two strands of nucleotides", "Opposite 5'' to 3'' orientation", "A–T pairs", "C–G pairs"]'::jsonb, '{"strand": ["A", "C", "G", "T", "T", "G", "C", "A"], "top_strand_left_to_right": true, "unit_note": "the dashes are hydrogen bonds: two in every A–T pair, three in every C–G pair", "labels_at": [{"x": 0.5, "y": 0.1, "label": "two strands of nucleotides, 5'' to 3'' opposite ways"}, {"x": 0.5, "y": 0.9, "label": "A–T and C–G pairs, joined by hydrogen bonds"}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=lane-b-gaps-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('bio-fluid-mosaic', 'ap_biology', 'membrane_bilayer', 'The plasma membrane: a bilayer with things embedded in it', 'Fluid mosaic', 'Phosphate heads face the water; tails face each other; the rest is embedded', 'The phospholipids form two leaflets: the hydrophilic phosphate heads face the watery surroundings on both sides and the hydrophobic tails face each other in the interior. Proteins, steroids such as cholesterol, glycoproteins and glycolipids sit within that framework, and the carbohydrate chains are all on the outside face.', 'A cross-section of a plasma membrane. Two rows of small circles are the phosphate heads of the phospholipids; the upper row faces the extracellular fluid and the lower row faces the cytoplasm, because both are watery and the heads are hydrophilic. From each head two lines run inward: these are the hydrophobic fatty acid tails, and the tails of the two rows meet in the middle, away from the water. Embedded in this framework are several other things. Two proteins cross the whole bilayer, so their hydrophobic regions are in contact with the fatty acids while their ends reach the water on each side. A small block sitting among the tails and reaching neither surface is a steroid, cholesterol in vertebrate animals. One of the crossing proteins and one single lipid head carry branched chains of sugars drawn above the membrane, making them a glycoprotein and a glycolipid; both carbohydrate chains are on the extracellular face, never the cytoplasmic one. All of these components move within the plane of the membrane, which is what the word fluid in fluid mosaic refers to. Illustrative data.', '', '', 'Heads to the water, tails to each other; the sugar chains are all on the outside face.', true, null, '["Phospholipid bilayer", "Embedded proteins", "Steroids (e.g., cholesterol in vertebrate animals)", "Glycoproteins", "Glycolipids"]'::jsonb, '{"lipids": 24, "inclusions": [{"kind": "protein", "x": 0.22}, {"kind": "steroid", "x": 0.4}, {"kind": "glycoprotein", "x": 0.6}, {"kind": "glycolipid", "x": 0.82}], "side_labels": [{"x": 0.02, "y": 0.3, "label": "outside the cell", "anchor": "start"}, {"x": 0.02, "y": 0.8, "label": "inside the cell", "anchor": "start"}], "unit_note": "the sugar chains mark the outside face; everything here drifts within the membrane", "labels_at": [{"x": 0.22, "y": 0.93, "label": "protein", "to": [0.22, 0.75]}, {"x": 0.4, "y": 0.09, "label": "steroid", "to": [0.4, 0.44]}, {"x": 0.62, "y": 0.93, "label": "glycoprotein", "to": [0.6, 0.75]}, {"x": 0.86, "y": 0.09, "label": "glycolipid", "to": [0.84, 0.26]}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=lane-b-gaps-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('chem-electrochemical-cell', 'ap_chemistry', 'electrochemical_cell', 'Reading a galvanic cell diagram', 'Anode, cathode, bridge', 'Oxidation at the anode; electrons through the wire; ions through the bridge', 'Each part of the diagram answers one question. The electrodes say where each half-reaction happens — oxidation at the anode, reduction at the cathode. The solutions hold the active species. The meter in the external circuit reads the cell potential. The salt bridge lets ions move between the half-cells so neither builds up a charge.', 'A galvanic cell. Two beakers each hold a half-cell solution containing the active species of one half-reaction, and an electrode dips into each solution. The left electrode is the anode, where oxidation occurs; the right electrode is the cathode, where reduction occurs. Which electrode changes mass, or evolves a gas, depends on the half-reactions, and this diagram names neither. A wire runs from the top of one electrode to the top of the other, and a meter sits in that external circuit to read the cell potential. Electrons travel through that wire in one direction only, from the anode to the cathode, shown by an arrow above the wire. An inverted U shaped salt bridge joins the two solutions: both of its ends are below the liquid surface, and it touches neither electrode. Ions move through it, cations toward the cathode and anions toward the anode, which keeps each half-cell electrically neutral and lets the current keep flowing. Illustrative data.', '', '', 'Electrons go anode to cathode through the wire; ions go through the bridge.', true, null, '["Electrodes", "Half-cell solutions", "Salt bridge", "Voltage/current measuring device"]'::jsonb, '{"anode_side": "left", "meter": "V", "meter_label": "voltmeter", "bridge_label": "salt bridge", "anode_label": "anode — oxidation", "cathode_label": "cathode — reduction", "unit_note": "electrons leave the anode; the bridge carries ions, so neither half-cell builds up charge", "labels_at": [{"x": 0.5, "y": 0.045, "label": "voltmeter"}, {"x": 0.235, "y": 0.985, "label": "anode — oxidation"}, {"x": 0.765, "y": 0.985, "label": "cathode — reduction"}, {"x": 0.5, "y": 0.445, "label": "salt bridge", "ann": true}, {"x": 0.07, "y": 0.84, "label": "half-cell solution", "anchor": "start", "ann": true}, {"x": 0.93, "y": 0.84, "label": "half-cell solution", "anchor": "end", "ann": true}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=lane-b-gaps-2026-10-11', now())
on conflict (figure_id) do nothing;

-- 3. Where each figure is shown, resolved by natural key (protocol §6).
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'bio-chloroplast', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_biology' and e.kind = 'diagram'
   and e.title = 'Chloroplast structure and where photosynthetic reactions occur' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'bio-mitochondrion', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_biology' and e.kind = 'diagram'
   and e.title = 'Mitochondrion: regions and functions in respiration' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'bio-dna-antiparallel', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_biology' and e.kind = 'diagram'
   and e.title = 'Antiparallel DNA double helix' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'bio-fluid-mosaic', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_biology' and e.kind = 'diagram'
   and e.title = 'Fluid mosaic model of the plasma membrane' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'chem-electrochemical-cell', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_chemistry' and e.kind = 'diagram'
   and e.title = 'Electrochemical cell diagram' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;

-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('bio-chloroplast', 'bio-mitochondrion', 'bio-dna-antiparallel', 'bio-fluid-mosaic', 'chem-electrochemical-cell') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('bio-chloroplast', 'bio-mitochondrion', 'bio-dna-antiparallel', 'bio-fluid-mosaic', 'chem-electrochemical-cell');
  if v_n <> 5 then
    raise exception 'expected 5 figures, found %', v_n;
  end if;
end $$;

commit;
